const now = new Date();
const caracasOffset = -4 * 60;
const localNow = new Date(now.getTime() + (now.getTimezoneOffset() + caracasOffset) * 60000);

const pad = (n) => String(n).padStart(2, '0');
const todayStr = `${localNow.getFullYear()}-${pad(localNow.getMonth() + 1)}-${pad(localNow.getDate())}`;

const localPlus4 = new Date(localNow.getTime() + 4 * 24 * 60 * 60000);
const todayPlus4Str = `${localPlus4.getFullYear()}-${pad(localPlus4.getMonth() + 1)}-${pad(localPlus4.getDate())}`;

const getField = (obj, regex) => {
  if (!obj) return '';
  for (const k of Object.keys(obj)) {
    if (regex.test(k)) {
      const v = obj[k];
      if (v !== undefined && v !== null) return v;
    }
  }
  return '';
};

const normalizeDate = (val) => {
  if (!val) return '';
  const str = String(val).trim();
  const raw = str.split(' ')[0].split('T')[0];
  const p = raw.split(/[\/\-]/);
  if (p.length === 3) {
    if (p[0].length === 4) {
      return `${p[0]}-${pad(p[1])}-${pad(p[2])}`;
    } else if (p[2].length === 4 || p[2].length === 2) {
      const yr = p[2].length === 2 ? '20' + p[2] : p[2];
      let day = p[0];
      let month = p[1];
      if (parseInt(month, 10) > 12 && parseInt(day, 10) <= 12) {
        day = p[1];
        month = p[0];
      }
      return `${yr}-${pad(month)}-${pad(day)}`;
    }
  }
  return raw;
};

const formatSpanishDate = (isoStr) => {
  if (!isoStr) return '';
  const parts = String(isoStr).trim().split(' ')[0].split('T')[0].split(/[\/\-]/);
  const months = [
    'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
    'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
  ];
  if (parts.length === 3) {
    if (parts[0].length === 4) {
      const day = parseInt(parts[2], 10);
      const monthIdx = parseInt(parts[1], 10) - 1;
      if (monthIdx >= 0 && monthIdx < 12 && !isNaN(day)) {
        return `${day} de ${months[monthIdx]}`;
      }
    } else {
      let day = parseInt(parts[0], 10);
      let monthIdx = parseInt(parts[1], 10) - 1;
      if (monthIdx >= 12 && day <= 12) {
        monthIdx = parseInt(parts[0], 10) - 1;
        day = parseInt(parts[1], 10);
      }
      if (monthIdx >= 0 && monthIdx < 12 && !isNaN(day)) {
        return `${day} de ${months[monthIdx]}`;
      }
    }
  }
  return isoStr;
};

const results = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const rawVence = getField(row, /^vence/i);
  const venceIso = normalizeDate(rawVence);
  const venceFormatted = formatSpanishDate(venceIso);
  const play = String(getField(row, /^play/i)).trim();
  const usuario = String(getField(row, /^usuario/i)).trim();
  const nombre = String(getField(row, /^nombre/i) || 'Cliente').trim();
  const apellido = String(getField(row, /^apellido/i)).trim();
  const telefono = String(getField(row, /^tel|phone/i)).replace(/\D/g, '');
  const rowNum = row.row_number ? parseInt(row.row_number, 10) : (i + 2);

  if (!usuario && !telefono && !nombre) continue;

  if (venceIso && venceIso === todayStr && play !== 'SENT' && (usuario || telefono)) {
    results.push({
      json: {
        ...row,
        row_number: rowNum,
        Nombre: nombre,
        Apellido: apellido,
        Teléfono: telefono,
        Usuario: usuario,
        Vence: venceIso,
        vence_formatted: venceFormatted,
        PLAY: play,
        category: 'vence_hoy'
      }
    });
  } else if (venceIso && venceIso === todayPlus4Str && play !== 'SENT4' && play !== 'SENT' && (usuario || telefono)) {
    results.push({
      json: {
        ...row,
        row_number: rowNum,
        Nombre: nombre,
        Apellido: apellido,
        Teléfono: telefono,
        Usuario: usuario,
        Vence: venceIso,
        vence_formatted: venceFormatted,
        PLAY: play,
        category: 'vence_4dias'
      }
    });
  } else if (venceIso && venceIso < todayStr && (usuario || telefono)) {
    results.push({
      json: {
        ...row,
        row_number: rowNum,
        Nombre: nombre,
        Apellido: apellido,
        Teléfono: telefono,
        Usuario: usuario,
        Vence: venceIso,
        vence_formatted: venceFormatted,
        PLAY: play,
        category: 'vencidos_pasados'
      }
    });
  }
}

return results;

const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/1';
const defaultInboxId = 16;

const results = [];
const items = $input.all();

let sourceItems = [];
try {
  sourceItems = $('Evaluar Vencimiento y Categorizar').all().map(i => i.json);
} catch (e) {
  sourceItems = [];
}

const getField = (obj, regex) => {
  if (!obj) return '';
  for (const k of Object.keys(obj)) {
    if (regex.test(k.trim())) {
      const v = obj[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
  }
  return '';
};

for (const item of items) {
  try {
    const itJson = item.json || {};
    // Extract phone from direct fields or Evolution API response
    const jid = itJson.data?.key?.remoteJid || itJson.remoteJid || '';
    const cleanJidPhone = String(jid).replace(/@.*/, '').replace(/\D/g, '');
    const directPhone = String(itJson.Teléfono || itJson.Telefono || itJson.phone || '').replace(/\D/g, '');
    const rawPhone = directPhone || cleanJidPhone;
    const cleanPhone = rawPhone.length > 0 ? (rawPhone.startsWith('+') ? rawPhone : `+${rawPhone}`) : '';

    // Match source row from Evaluar Vencimiento y Categorizar for rich DnSpace data
    let sourceRow = itJson;
    if (sourceItems.length > 0 && rawPhone) {
      const matched = sourceItems.find(r => {
        const rPhone = String(r.Teléfono || r.Telefono || '').replace(/\D/g, '');
        return rPhone && (rPhone === rawPhone || rawPhone.endsWith(rPhone) || rPhone.endsWith(rawPhone));
      });
      if (matched) sourceRow = matched;
    }

    const sheetNombre = getField(sourceRow, /^nombre/i);
    const sheetApellido = getField(sourceRow, /^apellido/i);
    const fullName = [sheetNombre, sheetApellido].filter(Boolean).join(' ').trim();
    const firstPurchase = getField(sourceRow, /^(1ra.*compra|primera.*compra|fecha.*compra|compra)/i);
    const sheetEmail = getField(sourceRow, /^(email|correo)/i);
    const sheetUsuario = getField(sourceRow, /^(usuario|user|username)/i);
    const venceFormatted = sourceRow.vence_formatted || getField(sourceRow, /^vence/i) || 'el día de HOY';

    if (!cleanPhone) {
      results.push({ json: { ...itJson, chatwoot_sync: 'skipped_no_phone' } });
      continue;
    }

    // 1. Search existing contact by phone
    let contactId = null;
    let existingContact = null;
    try {
      const searchRes = await this.helpers.httpRequest({
        method: 'GET',
        url: `${chatwootBase}/contacts/search?q=${encodeURIComponent(rawPhone)}`,
        headers: { 'api_access_token': chatwootToken },
        json: true
      });
      if (searchRes.payload && searchRes.payload.length > 0) {
        existingContact = searchRes.payload[0];
        contactId = existingContact.id;
      }
    } catch (e) {}

    // 2. Create contact if not exists
    if (!contactId) {
      try {
        const createPayload = {
          name: fullName || sheetNombre || 'Cliente',
          phone_number: cleanPhone
        };
        if (sheetEmail) createPayload.email = sheetEmail;
        const createRes = await this.helpers.httpRequest({
          method: 'POST',
          url: `${chatwootBase}/contacts`,
          headers: {
            'api_access_token': chatwootToken,
            'Content-Type': 'application/json'
          },
          body: createPayload,
          json: true
        });
        existingContact = createRes.payload?.contact;
        contactId = existingContact?.id;
      } catch (e) {}
    }

    if (!contactId) {
      results.push({ json: { ...itJson, chatwoot_sync: 'contact_failed' } });
      continue;
    }

    // 3. Enrich contact with DnSpace data:
    //    - name -> fullName from sheet (Nombre + Apellido)
    //    - additional_attributes.company_name -> preserve channel default name
    //    - additional_attributes.description -> 1ra compra (bio)
    //    - additional_attributes.usuario & custom_attributes.usuario -> service username
    try {
      if (!existingContact || !existingContact.additional_attributes) {
        const getContactRes = await this.helpers.httpRequest({
          method: 'GET',
          url: `${chatwootBase}/contacts/${contactId}`,
          headers: { 'api_access_token': chatwootToken },
          json: true
        });
        existingContact = getContactRes.payload || existingContact || {};
      }

      const existingAttrs = existingContact.additional_attributes || {};
      const existingCustomAttrs = existingContact.custom_attributes || {};
      const existingCompany = String(existingAttrs.company_name || '').trim();
      const currentContactName = String(existingContact.name || '').trim();

      let channelDefaultName = existingCompany;
      if (!channelDefaultName && currentContactName && currentContactName !== fullName) {
        channelDefaultName = currentContactName;
      }

      const updatePayload = {
        additional_attributes: {
          ...existingAttrs
        },
        custom_attributes: {
          ...existingCustomAttrs
        }
      };

      if (channelDefaultName) {
        updatePayload.additional_attributes.company_name = channelDefaultName;
      }
      if (firstPurchase) {
        updatePayload.additional_attributes.description = firstPurchase;
      }
      if (sheetUsuario) {
        updatePayload.additional_attributes.usuario = sheetUsuario;
        updatePayload.custom_attributes.usuario = sheetUsuario;
      }
      if (fullName) {
        updatePayload.name = fullName;
      }
      if (sheetEmail && !existingContact.email) {
        updatePayload.email = sheetEmail;
      }

      await this.helpers.httpRequest({
        method: 'PATCH',
        url: `${chatwootBase}/contacts/${contactId}`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: updatePayload,
        json: true
      });
    } catch (e) {}

    // 4. Find or create conversation in Chatwoot
    let conversationId = null;
    let convLabels = [];
    try {
      const convListRes = await this.helpers.httpRequest({
        method: 'GET',
        url: `${chatwootBase}/contacts/${contactId}/conversations`,
        headers: { 'api_access_token': chatwootToken },
        json: true
      });
      const convs = convListRes.payload || [];
      const match = convs.find(c => (Number(c.inbox_id) === defaultInboxId || Number(c.inbox_id) === 19) && c.status !== 'resolved')
                 || convs.find(c => Number(c.inbox_id) === defaultInboxId || Number(c.inbox_id) === 19)
                 || convs.find(c => c.status !== 'resolved')
                 || convs[0];
      if (match) {
        conversationId = match.id;
        convLabels = Array.isArray(match.labels) ? match.labels : [];
      }
    } catch (e) {}

    if (!conversationId) {
      try {
        const createConvRes = await this.helpers.httpRequest({
          method: 'POST',
          url: `${chatwootBase}/conversations`,
          headers: {
            'api_access_token': chatwootToken,
            'Content-Type': 'application/json'
          },
          body: { inbox_id: defaultInboxId, contact_id: contactId },
          json: true
        });
        conversationId = createConvRes.id;
        convLabels = [];
      } catch (e) {}
    }

    if (!conversationId) {
      results.push({ json: { ...itJson, chatwoot_sync: 'conv_failed' } });
      continue;
    }

    // 5. Update conversation labels: ensure stage-leads-ganados and funnel-totaltv-latina
    try {
      let cleanLabels = convLabels.filter(l => !l.startsWith('stage-'));
      if (!cleanLabels.includes('stage-leads-ganados')) cleanLabels.push('stage-leads-ganados');
      if (!cleanLabels.includes('funnel-totaltv-latina')) cleanLabels.push('funnel-totaltv-latina');

      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${conversationId}/labels`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: { labels: cleanLabels },
        json: true
      });
    } catch (e) {}

    // 6. Post private note documenting the outbound WhatsApp reminder
    const templateText = `*MENSAJE URGENTE*\n\n☀️Buenos días ${sheetNombre || 'Cliente'},\n\n📺Tu suscripción a Total TV *VENCE el día de HOY*\n\n💵Te invitamos a renovar tu plan, y seguir disfrutando del Entretenimiento sin Límites!\n\n¡Gracias por preferirnos!`;

    const noteContent = `📌 *Plantilla WhatsApp Enviada (Outbound)*\n• Plantilla: \`vencehoy\` (es)\n• Destinatario: ${cleanPhone}\n• Fecha/Hora: ${new Date().toLocaleString('es-VE', { timeZone: 'America/Caracas' })}\n\n📝 *Mensaje:*\n${templateText}`;

    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${conversationId}/messages`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: { content: noteContent, private: true },
        json: true
      });
    } catch (e) {}

    results.push({
      json: {
        ...itJson,
        chatwoot_contact_id: contactId,
        chatwoot_conversation_id: conversationId,
        chatwoot_sync: 'success'
      }
    });
  } catch (err) {
    results.push({ json: { ...item.json, chatwoot_sync: 'error', error: err.message } });
  }
}

return results;

